/* ---------------------------------------------------------- input parsers */
const intIn = (min, max) => (s) => { const t = String(s).trim(); const n = Number(t); return t !== '' && Number.isInteger(n) && n >= min && n <= max ? n : null; };
const listIn = (min, max, minLen, maxLen, compact) => (s) => {
  const t = String(s).trim();
  if (/[^\d\s,;|\[\]()-]/.test(t)) return null;
  const nums = compact && /^\d+$/.test(t) ? t.split('').map(Number) : (t.match(/\d+/g) || []).map(Number);
  return nums.length >= minLen && nums.length <= maxLen && nums.every((n) => n >= min && n <= max) ? nums : null;
};

const rpsIn = (s) => { const m = { rock: 0, paper: 1, scissors: 2, 0: 0, 1: 1, 2: 2 }; const v = m[String(s).trim().toLowerCase()]; return v === undefined ? null : v; };
const coinsIn = (s) => { const t = String(s).toUpperCase().replace(/[\s,]/g, ''); return /^[HT01]{3,12}$/.test(t) ? t.split('').map((c) => (c === 'H' || c === '1' ? 1 : 0)) : null; };
const distinct = (parse) => (s) => { const a = parse(s); return a && new Set(a).size === a.length ? a : null; };
const ascending = (parse) => (s) => { const a = parse(s); return a && a.every((x, i) => i === 0 || x >= a[i - 1]) ? a : null; };

const squareIn = (s) => { const m = String(s).trim().toLowerCase().match(/^([a-h])([1-8])$/); return m ? [m[1].charCodeAt(0) - 97, Number(m[2]) - 1] : null; };
const moveIn = (s) => { const m = { reload: 0, shoot: 1, shield: 2, cannon: 3, 0: 0, 1: 1, 2: 2, 3: 3 }; const v = m[String(s).trim().toLowerCase()]; return v === undefined ? null : v; };
const wordIn = (s) => { const t = String(s).trim().toLowerCase(); return /^[a-z]{5}$/.test(t) ? t.split('') : null; };

/* ---------------------------------------------------------------- levels */

/* ---------------------------------------------------------- small stages for the mini lessons */
const retOf = (snap) => { const r = snap && snap.ret; return r === null ? undefined : r; };
function miniStage(intro, names, draw) {
  return {
    render({ get, snap }) { return (draw ? draw(get, retOf(snap)) : '') + `<div class="readouts">${names.map((n) => valBadge(n, get(n))).join('')}${valBadge('answer', retOf(snap))}</div>`; },
    say({ snap }) { const r = retOf(snap); return r !== undefined ? `The function answers ${fmtVal(r)}.` : intro; },
  };
}
const miniNumbers = (names) => miniStage('Follow the numbers as the function works.', names);
const miniChess = (names) => miniStage('A chess board. Columns a to h are 0 to 7, rows 1 to 8 are 0 to 7.', names, (get) => {
  const fx = isNum(get('x1')) ? get('x1') : get('x'), fy = isNum(get('y1')) ? get('y1') : get('y'), tx = get('x2'), ty = get('y2');
  let cells = '';
  for (let r = 7; r >= 0; r--) for (let c = 0; c < 8; c++) {
    const cls = ['ch-cell', (r + c) % 2 ? 'light' : 'dark', c === fx && r === fy ? 'from' : '', c === tx && r === ty ? 'to' : ''].join(' ');
    cells += `<div class="${cls}">${c === fx && r === fy ? '<span class="ch-knight">&#9823;</span>' : ''}${c === tx && r === ty ? '<span class="ch-target">&#9678;</span>' : ''}</div>`;
  }
  return `<div class="ch-board" role="img" aria-label="Chess board">${cells}</div>`;
});
const miniVotes = miniStage('Players vote. We count the ballots for one player.', ['who', 'i', 'count'], (get) => {
  const votes = arrOf(get('votes')), i = get('i');
  return `<div class="wd-row">${votes.map((v, k) => `<span class="wd-tile plain${k === i ? ' look' : ''}">${esc(String(v))}</span>`).join('')}</div>`;
});
const miniWord = miniStage('The secret word is balls. Look for a letter in it.', ['letter', 'i'], (get) => {
  const secret = arrOf(get('secret')), i = get('i'), letter = get('letter'), guess = arrOf(get('guess'));
  const row = (arr, cur) => `<div class="wd-row">${arr.map((ch, k) => `<span class="wd-tile plain${k === cur ? ' look' : ''}">${esc(String(ch))}</span>`).join('')}</div>`;
  return `<div class="wd-rows"><small>secret</small>${row(secret, isNum(i) && !guess.length ? i : -1)}${guess.length ? `<small>guess</small>${row(guess, isNum(i) ? i : -1)}` : ''}</div>`;
});
const miniCard = miniStage('One playing card.', ['rank'], (get) => (isNum(get('rank')) ? cardHtml(get('rank'), 0) : ''));

/* A "part" is a small lesson of a bigger game, written compactly. No bug-hunting version: the student writes it from the rules. */
const PART_META = {}, PART_PLANS = {}, PART_KID = {}, PART_EMB = {};
function part(p) {
  const keep = p.keepBefore || '';
  const head = p.lines[0].match(/\(([^)]*)\)/)[1].split(',').map((s) => s.trim()).filter(Boolean);
  const locals = [...p.lines.join('\n').matchAll(/\blet (\w+)/g)].map((m) => m[1]);
  const names = p.watch || [...new Set([...head, ...locals])].slice(0, 5);
  PART_META[p.id] = [p.diff, p.theme]; PART_PLANS[p.id] = { task: p.task, steps: p.steps, decoys: p.traps }; PART_KID[p.id] = p.kid; PART_EMB[p.id] = p.emblem;
  const vals = {}; p.inputs.forEach((f) => { vals[f.id] = f.parse(f.value); });
  const code = (keep ? keep + '\n' : '') + p.lines.join('\n') + '\n' + p.driver(vals);
  const expected = new Interpreter(code, { trace: false, limit: 20000 }).run().out.join('\n');
  return {
    id: p.id, gameId: p.gameId || p.emblem, game: p.game, concept: p.concept, title: 'Table 0 · ' + p.title,
    objective: p.task, rules: p.rules, expected, nodebug: true, code,
    stage: miniStage(p.intro || 'Follow the values as the function works.', names, p.draw),
    diagnose: { question: '', options: ['', '', '', ''], answer: 0, bugLine: 1, explain: '' },
    fix: { keepBefore: keep, lines: p.lines, decoys: p.decoys || [], tests: p.tests },
    play: { inputs: p.inputs, driver: p.driver }, hints: p.hints,
  };
}

