  title: 'Golf: Hole in one',
  kid: 'A hole in one is the dream. You hit the ball once and it goes in. You will write isHoleInOne(strokes). Give it your hits on a hole. It answers yes if it was a hole in one.',
  task: 'Write isHoleInOne(strokes). Answer true when strokes is 1, otherwise false.',
  rules: ['One hit only is a hole in one.', 'Any other number of hits is not.', 'Strokes are never 0.'],
