const FAMS = [];
FAMILIES.forEach(([name, ids, main]) => {
  const members = ids.map((id) => LEVELS.find((L) => L.id === id)).filter(Boolean);
  if (members.length) FAMS.push({ name, main, members });
});
LEVELS.forEach((L) => { if (!FAMS.some((f) => f.members.includes(L))) FAMS.push({ name: L.game, main: L.id, members: [L] }); });
FAMS.forEach((f) => { f.diff = Math.min(...f.members.map((L) => LEVEL_META[L.id][0])); });
FAMS.sort((x, y) => x.diff - y.diff);
LEVELS.length = 0;
FAMS.forEach((f) => f.members.forEach((L, k) => { L.family = f.name; L.series = f.members.length > 1 ? { name: f.name, n: k + 1, of: f.members.length } : null; LEVELS.push(L); }));
LEVELS.forEach((L, i) => {
  L.difficulty = LEVEL_META[L.id][0]; L.theme = LEVEL_META[L.id][1]; L.topic = L.concept.split(' · ')[0];
  L.title = L.title.replace(/^Table \d+/, 'Table ' + (i + 1));
});

